// Shared integration contracts for the iron-ring-train MVP.
// Owned by the coordinator. Story workers IMPLEMENT or CONSUME these; they do not edit this file.
// Interfaces and plain data only, no logic, no Unity dependencies, so every system stays unit-testable.
//
// Who implements what (story -> interface):
//   001 Track      -> ITrackRuntime, ITrackNode
//   002 Habitat    -> IResourceInventory, IHabitatSystem
//   003 NPC        -> INpcRecruiter
//   004 Hub state  -> IHubStateSystem
//   005 Waypoint   -> IWaypointResolver
//   007 HUD        -> consumes all of the above through events
//
// Dependency rule: pure C# core classes take the interfaces they need through constructor parameters.
// MonoBehaviour wrappers adapt only. The composition root (Assets/Scripts/Bootstrap/) is written in the
// integration pass after all stories land; a story's own demo may wire fakes from its own folder.

using System;
using System.Collections.Generic;

namespace IronRing.Contracts
{
    /// <summary>Kind of node on the ring track.</summary>
    public enum TrackNodeKind
    {
        /// <summary>A hub (거점): the train docks, the player places resources and builds.</summary>
        Hub,
        /// <summary>A waypoint (경유지): an event or a combat encounter happens.</summary>
        Waypoint
    }

    /// <summary>One node on the ring track. Read from track data, never hardcoded.</summary>
    public interface ITrackNode
    {
        /// <summary>Stable id from track data.</summary>
        string Id { get; }
        /// <summary>Position in ring order, 0-based.</summary>
        int Index { get; }
        /// <summary>Hub or Waypoint.</summary>
        TrackNodeKind Kind { get; }
        /// <summary>Hub id when Kind is Hub, otherwise null.</summary>
        string HubId { get; }
        /// <summary>스토리 048. 잠긴 역(선로가 아직 열리지 않음): 열차가 멈추지 않고 지나간다(Arrived·이벤트·승객 없음). 기본 false.</summary>
        bool IsLocked => false;
    }

    /// <summary>
    /// 스토리 048. 잠긴 역(ring-track.json `_locked`)을 여는 서비스. EconomyInstaller가 Composing에서 등록한다.
    /// 황동골이 TownTiers.json `_unlockHubs`가 있는 등급에 오르면 정산이 Open을 부른다.
    /// </summary>
    public interface ILineOpener
    {
        /// <summary>hubId 역이 열려 있는지(선로에 없는 id·이미 열린 역은 true).</summary>
        bool IsOpen(string hubId);
        /// <summary>hubId 역을 연다. 이미 열려 있으면 무시(HubOpened 없음).</summary>
        void Open(string hubId);
        /// <summary>역이 열렸을 때 한 번(거점 id).</summary>
        event Action<string> HubOpened;
        /// <summary>아직 잠긴 역 id(선로 순서).</summary>
        IReadOnlyList<string> LockedHubIds { get; }
    }

    /// <summary>Story 001. The ring track and the train on it. The ring never breaks.</summary>
    public interface ITrackRuntime
    {
        /// <summary>All nodes in ring order.</summary>
        IReadOnlyList<ITrackNode> Nodes { get; }
        /// <summary>Node the train is at or heading from.</summary>
        ITrackNode CurrentNode { get; }
        /// <summary>Number of full laps completed so far.</summary>
        int Lap { get; }
        /// <summary>True while docked at a hub or held by an encounter.</summary>
        bool IsHeld { get; }

        /// <summary>Raised after the train reaches a node.</summary>
        event Action<ITrackNode> Arrived;
        /// <summary>Raised when the train returns to the first node; argument is the new lap count.</summary>
        event Action<int> LapCompleted;

        /// <summary>Player departs from the current hub. No-op while a hold is active.</summary>
        void Depart();
        /// <summary>Stop movement for a reason (combat, event). Reasons stack; all must be released.</summary>
        void RequestHold(string reason);
        /// <summary>Release a hold previously requested with the same reason.</summary>
        void ReleaseHold(string reason);
    }

    /// <summary>Story 002. The player's resource stock. Resource ids come from data.</summary>
    public interface IResourceInventory
    {
        /// <summary>Current amount; 0 for an unknown id.</summary>
        int Get(string resourceId);
        /// <summary>Add a non-negative amount.</summary>
        void Add(string resourceId, int amount);
        /// <summary>Spend if available; returns false and changes nothing otherwise.</summary>
        bool TrySpend(string resourceId, int amount);
        /// <summary>Copy of every resource and amount.</summary>
        IReadOnlyDictionary<string, int> Snapshot();
        /// <summary>resourceId, new amount.</summary>
        event Action<string, int> Changed;
    }

    /// <summary>Story 002. Habitat slots per hub and the combo check that raises the event flag.</summary>
    public interface IHabitatSystem
    {
        /// <summary>Place a resource from the inventory into a hub slot; false if refused.</summary>
        bool TryPlace(string hubId, int slotIndex, string resourceId);
        /// <summary>Return a placed resource to the inventory; false if the slot is empty.</summary>
        bool TryRemove(string hubId, int slotIndex);
        /// <summary>Resource id in a slot, or null when empty.</summary>
        string SlotContent(string hubId, int slotIndex);
        /// <summary>True when the hub's habitat combo is complete.</summary>
        bool IsHabitatComplete(string hubId);
        /// <summary>True when the hub's event flag is set.</summary>
        bool IsEventFlagSet(string hubId);
        /// <summary>hubId whose event flag was just raised.</summary>
        event Action<string> EventFlagRaised;
    }

    /// <summary>Story 003. Unique NPC pool and the probabilistic join on a flagged hub visit.</summary>
    public interface INpcRecruiter
    {
        /// <summary>Called once per hub visit (integration wires it to ITrackRuntime.Arrived). At most one roll per visit.</summary>
        void OnHubVisited(string hubId);
        /// <summary>Ids of NPCs that joined this hub.</summary>
        IReadOnlyList<string> NpcsAt(string hubId);
        /// <summary>hubId, npcId.</summary>
        event Action<string, string> NpcJoined;
        /// <summary>스토리 023. 그 서식지 종류를 원하는 모든 NPC id(거점 무관, 풀 순서). 도감 "찾아오는 이"의 ??? 개수에 쓴다.</summary>
        IReadOnlyList<string> CandidatesOf(string habitatTypeId) => Array.Empty<string>();
        /// <summary>스토리 023. 그 서식지 종류를 원하는 NPC 가운데 실제로 합류한 id(합류 순서).</summary>
        IReadOnlyList<string> JoinedOf(string habitatTypeId) => Array.Empty<string>();
        /// <summary>스토리 023. npcId, hubId. 승객이 내려 합류한 순간(NpcJoined 직후). 표현이 열차 칸→집 도착 연출에 쓴다.</summary>
        event Action<string, string> NpcArrived { add { } remove { } }
    }

    /// <summary>Story 004. Prosperity per hub, ruin transition, and the run-lost rule (all hubs ruined).</summary>
    public interface IHubStateSystem
    {
        /// <summary>All hub ids from data; not fixed to 4.</summary>
        IReadOnlyList<string> HubIds { get; }
        /// <summary>Current prosperity value.</summary>
        float GetProsperity(string hubId);
        /// <summary>True once the hub turned to ruins. Ruins stay on the track and remain visitable.</summary>
        bool IsRuined(string hubId);
        /// <summary>True when every hub is ruined.</summary>
        bool IsRunLost { get; }
        /// <summary>Apply a prosperity change from NPCs, facilities, combat or events. Reason is for logs.</summary>
        void ApplyDelta(string hubId, float delta, string reason);
        /// <summary>Per-lap tick (integration wires it to ITrackRuntime.LapCompleted).</summary>
        void OnLapCompleted(int lap);

        /// <summary>hubId, new prosperity.</summary>
        event Action<string, float> ProsperityChanged;
        /// <summary>hubId that just became ruins.</summary>
        event Action<string> HubRuined;
        /// <summary>Raised once when the last hub is ruined.</summary>
        event Action RunLost;
    }

    /// <summary>Result of a waypoint encounter.</summary>
    public enum EncounterOutcome
    {
        /// <summary>An event resolved (story 039: rest stops only run events; combat outcomes were removed).</summary>
        EventResolved
    }

    /// <summary>Story 005 / 039. Rest-stop (waypoint) events: every arrival at a rest stop resolves exactly one event.</summary>
    public interface IWaypointResolver
    {
        /// <summary>Story 039: boarding-chance bonus granted by the event that just resolved at this stop (0 = none). Read by passengers on EncounterEnded.</summary>
        float BoardChanceBonus => 0f;
        /// <summary>Story 039: extra recipes the event that just resolved unlocks in the codex (on top of the per-event amount).</summary>
        int CodexUnlocks => 0;
        /// <summary>Called when the train arrives at a waypoint (integration wires it to ITrackRuntime.Arrived). Holds the track while active.</summary>
        void OnWaypointArrived(ITrackNode node);
        /// <summary>True while an event is in progress.</summary>
        bool IsEncounterActive { get; }
        /// <summary>Node where an encounter began.</summary>
        event Action<ITrackNode> EncounterStarted;
        /// <summary>Node and outcome when an encounter ended.</summary>
        event Action<ITrackNode, EncounterOutcome> EncounterEnded;
    }

    /// <summary>Injectable random source so every probabilistic rule is deterministic under test.</summary>
    public interface IRandomSource
    {
        /// <summary>Uniform value in [0, 1).</summary>
        float NextFloat();
        /// <summary>Uniform integer in [minInclusive, maxExclusive).</summary>
        int NextInt(int minInclusive, int maxExclusive);
    }

    // ----- 거점 내부(스토리 012~014) -----
    // 거점에 정차하면 내부 탑뷰(선로 위·아래 각 3×6칸)로 들어간다. 칸은 잔해로 시작해 조사로 드러나고,
    // 드러난 빈 터에는 인벤토리의 아이템을, 시설 부지에는 방어시설을 놓는다. 배치한 아이템의 태그 조합이
    // 거점 조건을 채우면 서식지가 완성된다(IHabitatSystem의 IsHabitatComplete/EventFlagRaised를 그대로 쓴다).

    /// <summary>거점 내부 칸의 상태. 데이터가 결과 확률을 정한다.</summary>
    public enum InteriorCellState
    {
        /// <summary>잔해. 아직 조사하지 않았다.</summary>
        Rubble,
        /// <summary>조사됨: 빈 터. 아이템을 놓을 수 있다.</summary>
        Empty,
        /// <summary>조사됨: 옛 시설 부지. 방어시설을 지을 수 있다.</summary>
        FacilityPlot,
        /// <summary>빈 터에 아이템이 놓임.</summary>
        ItemPlaced
    }

    /// <summary>거점 내부의 칸 하나. Index는 0부터, 위 구역 3×6 다음 아래 구역 3×6 순서.</summary>
    public interface IInteriorCell
    {
        /// <summary>0..35.</summary>
        int Index { get; }
        /// <summary>구역 안의 줄(0..2)과 칸(0..5).</summary>
        int Row { get; }
        int Column { get; }
        /// <summary>true면 선로 위 구역, false면 아래 구역.</summary>
        bool IsUpper { get; }
        InteriorCellState State { get; }
        /// <summary>ItemPlaced일 때 아이템 id, 아니면 null.</summary>
        string ItemId { get; }
    }

    /// <summary>조사 결과. 묻힌 아이템·자원은 즉시 인벤토리/재고로 들어가고 칸은 Empty가 된다.</summary>
    public enum InvestigationResult
    {
        Empty,
        FoundItem,
        FoundResource,
        FacilityPlot
    }

    /// <summary>스토리 012. 거점 내부 칸과 조사 규칙. 정차마다 조사 횟수가 데이터값으로 초기화된다.</summary>
    public interface IHubInterior
    {
        /// <summary>거점의 칸 36개. 거점 id는 hub-1..hub-4.</summary>
        IReadOnlyList<IInteriorCell> Cells(string hubId);
        /// <summary>이번 정차에서 남은 조사 횟수.</summary>
        int InvestigationsLeft(string hubId);
        /// <summary>잔해 칸이고 남은 횟수가 있을 때만 true.</summary>
        bool CanInvestigate(string hubId, int cellIndex);
        /// <summary>조사: 결과를 돌려주고 칸 상태를 바꾼다. 발견한 아이템/자원의 id는 FoundId로 알린다.</summary>
        InvestigationResult Investigate(string hubId, int cellIndex, out string foundId);
        /// <summary>정차 시 호출(통합이 ITrackRuntime.Arrived에 연결). 조사 횟수를 초기화한다.</summary>
        void OnDocked(string hubId);
        /// <summary>hubId, cellIndex.</summary>
        event Action<string, int> CellChanged;
        /// <summary>hubId, 남은 횟수.</summary>
        event Action<string, int> InvestigationsChanged;
    }

    /// <summary>스토리 013. 아이템 인벤토리. 아이템 id와 태그, 제작 비용은 데이터에서 온다.</summary>
    public interface IItemInventory
    {
        int Count(string itemId);
        void Add(string itemId, int amount);
        bool TryRemove(string itemId, int amount);
        IReadOnlyDictionary<string, int> Snapshot();
        /// <summary>자원(IResourceInventory)을 써서 제작. 비용이 모자라면 false.</summary>
        bool CanCraft(string itemId);
        bool TryCraft(string itemId);
        /// <summary>itemId, 새 수량.</summary>
        event Action<string, int> Changed;
    }

    /// <summary>스토리 013. 아이템을 내부 칸에 놓거나 회수한다. IHubInterior의 칸 상태를 갱신한다.</summary>
    public interface IItemPlacement
    {
        bool CanPlace(string hubId, int cellIndex, string itemId);
        bool TryPlace(string hubId, int cellIndex, string itemId);
        bool TryPickUp(string hubId, int cellIndex);
        /// <summary>hubId, cellIndex, itemId.</summary>
        event Action<string, int, string> ItemPlaced;
        event Action<string, int, string> ItemRemoved;
    }

    /// <summary>스토리 014. 거점 단계. 폐허에서 시작해 복구·정착하고, 방치하면 붕괴한다.</summary>
    public enum HubPhase
    {
        Ruined,
        Recovering,
        Settled,
        Collapsed
    }

    // ----- 서식지 종류와 연결 판정(스토리 016) -----
    // 서식지 종류는 데이터 카탈로그다. 각 종류는 "타일(아이템) id, 필요한 칸 수"로 정의되고, 같은 타일이 상하좌우로
    // 이어진 묶음(모양 무관, 선로 건너편은 이어지지 않음)의 크기가 필요한 칸 수 이상이면 완성된다.

    /// <summary>완성된 서식지 하나. 같은 거점에 여러 개가 있을 수 있다.</summary>
    public sealed class HabitatCluster
    {
        /// <summary>서식지 종류 id (카탈로그).</summary>
        public string TypeId;
        /// <summary>이 서식지를 이루는 칸 번호들.</summary>
        public IReadOnlyList<int> Cells;
    }

    /// <summary>스토리 016. 거점별 완성 서식지 목록. IHabitatSystem.IsHabitatComplete는 하나라도 완성되면 true다.</summary>
    public interface IHabitatClusters
    {
        /// <summary>서식지 카탈로그의 모든 종류 id.</summary>
        IReadOnlyList<string> HabitatTypeIds { get; }
        /// <summary>해당 거점에서 지금 완성된 서식지들.</summary>
        IReadOnlyList<HabitatCluster> CompletedAt(string hubId);
        /// <summary>hubId, 서식지 종류 id. 새로 완성될 때 1회.</summary>
        event Action<string, string> HabitatCompleted;
        /// <summary>hubId, 서식지 종류 id. 타일이 빠져 더는 완성이 아닐 때.</summary>
        event Action<string, string> HabitatBroken;
    }

    /// <summary>
    /// 스토리 021. 서식지 레시피(완성 조건) 도감. 런 시작 때 시작 레시피만 알고, 바퀴·경유지 이벤트·전투 승리·우연한 완성(발견)으로 하나씩 해금한다.
    /// 해금 여부는 완성 판정을 막지 않는다(모르는 레시피도 완성되면 그대로 인정되고 "discover"로 해금된다).
    /// </summary>
    public interface IHabitatCodex
    {
        /// <summary>typeId 레시피를 알고 있으면 true.</summary>
        bool IsUnlocked(string typeId);
        /// <summary>해금된 종류 id들(해금 순서).</summary>
        IReadOnlyList<string> UnlockedTypeIds { get; }
        /// <summary>typeId를 해금한다. 카탈로그에 없거나 이미 해금이면 false. source: "start" | "lap" | "event" | "victory" | "discover" | "board" | "teach".</summary>
        bool TryUnlock(string typeId, string source);
        /// <summary>스토리 030. typeId를 연 출처("start"·"board"·"teach"·"discover" 등). 모르면 null.</summary>
        string UnlockSourceOf(string typeId) => null;
        /// <summary>스토리 030. typeId를 건네거나 가르쳐 준 NPC id("board"·"teach"일 때만). 없으면 null.</summary>
        string UnlockNpcOf(string typeId) => null;
        /// <summary>typeId, source. 새로 해금될 때 1회(시작 레시피는 생성 때 해금되므로 발생하지 않는다).</summary>
        event Action<string, string> RecipeUnlocked;
    }

    // ----- NPC 집(배정 서식지)과 대화·상호작용(스토리 017) -----

    /// <summary>NPC 한 명의 집: 합류 때 배정된 거점의 완성 서식지 하나와 그 칸들.</summary>
    public sealed class NpcHome
    {
        public string NpcId;
        public string HubId;
        /// <summary>서식지 종류 id (카탈로그).</summary>
        public string HabitatTypeId;
        /// <summary>집 서식지를 이루는 칸 번호들. 서식지가 깨지면 빈 목록.</summary>
        public IReadOnlyList<int> Cells;
    }

    /// <summary>스토리 017. NPC별 집 배정. 합류 때 그 NPC의 서식지 종류 가운데 완성된 묶음 하나를 집으로 잡고, 깨지면 칸을 비우고 다시 완성되면 되돌린다.</summary>
    public interface INpcHomes
    {
        /// <summary>npcId의 집. 합류하지 않은 NPC면 null.</summary>
        NpcHome HomeOf(string npcId);
        /// <summary>hubId에 사는 NPC들의 집.</summary>
        IReadOnlyList<NpcHome> HomesAt(string hubId);
        /// <summary>npcId. 집이 생기거나 칸이 바뀌거나 비었을 때.</summary>
        event Action<string> HomeChanged;
    }

    /// <summary>NPC 대화 패널의 선택지 하나.</summary>
    public sealed class NpcInteractionOption
    {
        public string Id;
        /// <summary>한국어 버튼 글자.</summary>
        public string Label;
        public bool Enabled;
        /// <summary>비활성 이유(한국어), 활성이면 null.</summary>
        public string Reason;
    }

    /// <summary>스토리 017. NPC 대화와 상호작용. 상태(정차당 1회 같은 제한)는 이 시스템이 소유한다.</summary>
    public interface INpcInteraction
    {
        /// <summary>표시 이름(직업명).</summary>
        string DisplayName(string npcId);
        /// <summary>현재 대사. NextLine을 부르기 전에는 첫 줄.</summary>
        string CurrentLine(string npcId);
        /// <summary>다음 대사로 넘기고 그 줄을 돌려준다(끝이면 처음으로).</summary>
        string NextLine(string npcId);
        /// <summary>지금 고를 수 있는 선택지(데이터). 라벨은 한국어.</summary>
        IReadOnlyList<NpcInteractionOption> Options(string npcId);
        /// <summary>선택지를 실행한다. resultText는 패널에 보여 줄 한국어 결과 문장.</summary>
        bool TryInteract(string npcId, string optionId, out string resultText);
        /// <summary>npcId, optionId. 실행에 성공했을 때.</summary>
        event Action<string, string> Interacted;
        /// <summary>스토리 023. npcId의 출신지 이름(한국어, 예: "북쪽 고개"). 모르면 null. 대화 패널의 "&lt;출신지&gt; 출신" 줄에 쓴다.</summary>
        string Origin(string npcId) => null;
    }

    /// <summary>런이 끝난 이유.</summary>
    public enum RunLossReason
    {
        None,
        /// <summary>정착했던 거점이 모두 붕괴.</summary>
        AllSettledCollapsed,
        /// <summary>기한 안에 정착한 거점이 없음.</summary>
        DeadlineExpired,
        /// <summary>스토리 040. 잔고가 0 아래인 채 정산이 데이터(Economy.json _bankruptLaps) 바퀴 연속 = 파산.</summary>
        Bankrupt
    }

    /// <summary>스토리 014가 구현(선택 계약, IHubDevelopment와 함께 등록). 패배 화면이 제목을 사유별로 고르는 데 쓴다.</summary>
    public interface IRunLossInfo
    {
        RunLossReason LastLossReason { get; }
    }

    /// <summary>스토리 014. 거점 단계와 기한. IHubStateSystem의 번영·RunLost와 함께 쓴다.</summary>
    public interface IHubDevelopment
    {
        HubPhase GetPhase(string hubId);
        /// <summary>한 번이라도 정착한 적이 있는지.</summary>
        bool HasEverSettled(string hubId);
        /// <summary>첫 정착 기한까지 남은 바퀴 수(데이터값에서 감소). 정착 후에는 0 이하가 되어도 패배가 아니다.</summary>
        int LapsUntilDeadline { get; }
        /// <summary>hubId, 새 단계.</summary>
        event Action<string, HubPhase> PhaseChanged;
    }

    /// <summary>
    /// 스토리 023. 열차 승객. NPC는 경유지 이벤트·전투 승리 뒤 각자 확률·탑승 조건으로 타며 제안과 힌트를 남기고,
    /// 거점에 정차했을 때 원하는 서식지가 완성되어 있고 숨은 조건을 채우면 내려 합류한다. 인내 바퀴가 지나면 다음 경유지에서 떠난다.
    /// </summary>
    public interface IPassengers
    {
        /// <summary>지금 탄 승객 id(탑승 순서).</summary>
        IReadOnlyList<string> PassengerIds { get; }
        /// <summary>승객의 제안 문장(한국어).</summary>
        string Proposal(string npcId);
        /// <summary>숨은 조건에 대한 힌트 문장(한국어). 조건 수치를 다 드러내지 않는다.</summary>
        string Hint(string npcId);
        /// <summary>출신지 이름(한국어).</summary>
        string OriginName(string npcId);
        /// <summary>탑승 뒤 지난 바퀴 수. 타고 있지 않으면 0.</summary>
        int LapsAboard(string npcId);
        /// <summary>npcId, waypointId.</summary>
        event Action<string, string> Boarded;
        /// <summary>npcId, hubId.</summary>
        event Action<string, string> Disembarked;
        /// <summary>집을 못 찾고 떠난 npcId.</summary>
        event Action<string> Left;
        /// <summary>데모·시험용 탑승. force면 자리·출신지·탑승 조건을 무시한다. 이미 합류했거나 타고 있으면 false.</summary>
        bool TryBoard(string npcId, string waypointId, bool force);
    }

    // ----- 런의 끝과 번영 예보(스토리 028) -----

    /// <summary>스토리 028. 런 결과. 기한이 지나면 정착 수로 정해진다(4곳 승리, 1~3곳 부분 성공, 0곳 패배). 정착 거점 전부 붕괴도 패배.</summary>
    public enum RunOutcome
    {
        /// <summary>런이 아직 진행 중.</summary>
        None,
        /// <summary>모든 거점이 정착한 채 기한을 맞음.</summary>
        Victory,
        /// <summary>일부 거점만 정착한 채 기한을 맞음.</summary>
        Partial,
        /// <summary>정착 0곳으로 기한을 맞았거나, 정착했던 거점이 모두 붕괴함.</summary>
        Defeat
    }

    /// <summary>스토리 028. 결과 화면 한 줄(거점 하나)의 요약. 런이 끝난 순간의 값이다.</summary>
    public sealed class RunHubSummary
    {
        /// <summary>거점 id.</summary>
        public string HubId;
        /// <summary>끝난 순간의 단계.</summary>
        public HubPhase Phase;
        /// <summary>끝난 순간의 번영.</summary>
        public float Prosperity;
        /// <summary>합류한 NPC 수.</summary>
        public int NpcCount;
    }

    /// <summary>
    /// 스토리 028. 런의 끝. 기한(HubProfiles.json _deadlineLaps)은 정착 여부와 상관없이 항상 런을 끝낸다.
    /// 끝나면 IHubStateSystem.IsRunLost도 true가 되어(= "런 종료", 결과와 무관) 열차·조작이 멈춘다. IRunLossInfo는 패배 사유만 그대로 준다.
    /// </summary>
    public interface IRunResult
    {
        /// <summary>런이 끝났는지.</summary>
        bool IsOver { get; }
        /// <summary>결과(진행 중이면 None).</summary>
        RunOutcome Outcome { get; }
        /// <summary>끝난 순간 정착(Settled) 단계인 거점 수.</summary>
        int SettledCount { get; }
        /// <summary>전체 거점 수.</summary>
        int HubCount { get; }
        /// <summary>끝난 순간까지 적용된 바퀴 수.</summary>
        int Laps { get; }
        /// <summary>거점별 요약(데이터 순서). 진행 중에는 빈 목록.</summary>
        IReadOnlyList<RunHubSummary> Hubs { get; }
        /// <summary>런이 끝날 때 한 번.</summary>
        event Action RunEnded;
    }

    /// <summary>스토리 028. 번영 예보(배너 "번영 N/40 · 다음 바퀴 +M", 거점 패널 "정착까지 번영 K").</summary>
    public interface IProsperityForecast
    {
        /// <summary>지금 상태로 다음 바퀴 틱에 더해질 번영(경유지 이벤트·전투 결과는 빼고, 붕괴 거점은 0).</summary>
        float NextLapDelta(string hubId);
        /// <summary>해당 거점의 정착 기준 번영(데이터 _settledThreshold).</summary>
        float SettledThreshold(string hubId);
    }

    /// <summary>
    /// 스토리 028 (QA S3-1). 완성 서식지의 칸 구성이 바뀌었지만 종류별 완성 수는 그대로일 때(완성 묶음에 칸이 붙거나 빠짐) 알린다.
    /// 수가 바뀌는 경우는 기존 HabitatCompleted/HabitatBroken이 알리므로 여기서는 내지 않는다. 테두리·건물 표시가 이 신호로 다시 그린다.
    /// ClusterHabitatSystem이 구현한다(IHabitatClusters와 같은 인스턴스로 GameServices에 등록).
    /// </summary>
    public interface IHabitatClusterChanges
    {
        /// <summary>hubId, 서식지 종류 id. 그 종류의 완성 묶음 칸 구성이 바뀔 때마다 1회.</summary>
        event Action<string, string> HabitatChanged;
    }

    // ----- 경제 기반(스토리 040, design/game-brief.md "돈(마르크)"·"휴식지는 시장이다") -----

    /// <summary>스토리 040. 회사 돈(마르크). 정수만 쓴다.</summary>
    public interface IMoney
    {
        /// <summary>현재 잔고(유지비 강제 지출로 0 아래가 될 수 있다).</summary>
        int Balance { get; }
        /// <summary>amount(&gt;=0)를 더한다. 음수면 false.</summary>
        bool TryGain(int amount, string reason);
        /// <summary>amount(&gt;=0)를 뺀다. 잔고가 모자라면 아무것도 바꾸지 않고 false.</summary>
        bool TrySpend(int amount, string reason);
        /// <summary>강제 지출(유지비). 잔고가 모자라도 빼서 0 아래가 될 수 있다.</summary>
        void Charge(int amount, string reason);
        /// <summary>잔고가 바뀔 때마다.</summary>
        event Action Changed;
    }

    /// <summary>스토리 040. 장부 항목 종류.</summary>
    public enum LedgerKind
    {
        /// <summary>승객 운임(수입).</summary>
        Fare,
        /// <summary>화물 판매(수입).</summary>
        Sale,
        /// <summary>화물 구매(지출).</summary>
        Purchase,
        /// <summary>열차 유지비(지출).</summary>
        Upkeep,
        /// <summary>스토리 045. 완성 건물 수입(_income 합).</summary>
        Income
    }

    /// <summary>스토리 040. 장부 한 줄. Amount는 부호 있음(수입 +, 지출 -).</summary>
    public sealed class LedgerEntry
    {
        /// <summary>항목이 속한 바퀴(진행 중인 바퀴 = 완료 바퀴 + 1).</summary>
        public int Lap;
        /// <summary>항목 종류.</summary>
        public LedgerKind Kind;
        /// <summary>금액(수입 +, 지출 -).</summary>
        public int Amount;
        /// <summary>메모(품목 id·수량, 승객 id 등).</summary>
        public string Note;
    }

    /// <summary>스토리 040. 바퀴 장부. 거점 복귀(LapCompleted)마다 유지비를 적고 정산한다.</summary>
    public interface ILedger
    {
        /// <summary>모든 항목(적은 순서).</summary>
        IReadOnlyList<LedgerEntry> Entries { get; }
        /// <summary>지금 적히는 바퀴 번호.</summary>
        int CurrentLap { get; }
        /// <summary>lap 바퀴의 kind 합계(부호 있음).</summary>
        int Total(int lap, LedgerKind kind);
        /// <summary>런 전체 수입 합(양수).</summary>
        int TotalIncome { get; }
        /// <summary>런 전체 지출 합(양수).</summary>
        int TotalExpense { get; }
        /// <summary>정산 직후: 바퀴 번호, 그 바퀴 순이익.</summary>
        event Action<int, int> LapSettled;
    }

    // ----- 타일 비용(스토리 041) -----

    /// <summary>스토리 041. 타일·장식 배치 가격(ItemCatalog.json _price). 배치 때 잔고에서 빠지고, 회수·철거·되돌리기 때 _refundRatio만큼 돌아온다.</summary>
    public interface IPlacementCost
    {
        /// <summary>아이템 1개 배치 가격(마르크, 모르는 id면 0).</summary>
        int PriceOf(string itemId);
        /// <summary>아이템 1개 회수 때 돌려받는 금액.</summary>
        int RefundOf(string itemId);
        /// <summary>지금 잔고로 놓을 수 있는지.</summary>
        bool CanAfford(string itemId);
    }

    // ── 주민·마을 등급(스토리 042) ─────────────────────────────

    /// <summary>
    /// 스토리 042·045(가벼운 경제). 마을 거점(hub-1)의 일반 주민. 고유 NPC(INpcRecruiter)는 별도다.
    /// 바퀴 정산 때: 주거 &gt; 주민이면 +1(빛 ≥ 주민 × _lightPerResident면 +2, 주거를 넘지 않음), 주거 &lt; 주민이면 −1(최소 1).
    /// </summary>
    public interface IPopulation
    {
        /// <summary>일반 주민 수(시작 3, 최소 1).</summary>
        int Residents { get; }
        /// <summary>주거 = 기본 주거 + 완성 건물 _housing 합.</summary>
        int Housing { get; }
        /// <summary>빛 = 완성 건물 _light 합.</summary>
        int Light { get; }
        /// <summary>값이 바뀌었을 때(정산, 건물 완성·파손).</summary>
        event Action Changed;
        /// <summary>스토리 048. "현재 마을": 내부가 열린 거점, 아니면 열차가 선 (열린) 역, 아니면 hub-1. Residents·Housing·Light는 이 마을 값.</summary>
        string CurrentHubId => "hub-1";
        /// <summary>스토리 048. hubId 마을의 주민(모르는 마을·잠긴 마을 0).</summary>
        int ResidentsAt(string hubId) => Residents;
        /// <summary>스토리 048. hubId 마을의 주거.</summary>
        int HousingAt(string hubId) => Housing;
        /// <summary>스토리 048. hubId 마을의 빛.</summary>
        int LightAt(string hubId) => Light;
    }

    /// <summary>스토리 042. 창고 거점의 마을 등급(0 폐허 → 1 정착촌 → 2 마을 → 3 도시, TownTiers.json). 등급은 내려가지 않는다.</summary>
    public interface ITownTier
    {
        /// <summary>지금 등급 번호(0부터).</summary>
        int Tier { get; }
        /// <summary>지금 등급 id(ruin|camp|village|city).</summary>
        string TierId { get; }
        /// <summary>지금 등급 이름(폐허·정착촌·마을·도시).</summary>
        string TierName { get; }
        /// <summary>다음 등급 번호(최고면 지금 등급).</summary>
        int NextTier { get; }
        /// <summary>최고 등급인지.</summary>
        bool IsMax { get; }
        /// <summary>다음 등급에 필요한 주민 수(최고면 0).</summary>
        int NextResidentsNeed { get; }
        /// <summary>다음 등급에 필요한 번영(최고면 0).</summary>
        int NextProsperityNeed { get; }
        /// <summary>등급이 올랐을 때(새 등급 번호).</summary>
        event Action<int> TierChanged;
        /// <summary>지금까지 등급이 연 레시피 id(누적).</summary>
        IReadOnlyList<string> UnlockedRecipeIds { get; }
        /// <summary>지금까지 등급이 연 열차 업그레이드 id(누적, 043이 쓴다).</summary>
        IReadOnlyList<string> UnlockedUpgradeIds { get; }
        /// <summary>스토리 048. "현재 마을"(IPopulation.CurrentHubId와 같은 규칙). Tier·TierName·Next*는 이 마을 값.</summary>
        string CurrentHubId => "hub-1";
        /// <summary>스토리 048. hubId 마을의 등급 번호(모르는 마을 0).</summary>
        int TierAt(string hubId) => Tier;
        /// <summary>스토리 048. hubId 마을의 등급 이름.</summary>
        string TierNameAt(string hubId) => TierName;
        /// <summary>스토리 048. hubId 마을의 다음 등급 조건. 최고 등급이면 false(0, 0).</summary>
        bool NextNeedsAt(string hubId, out int residents, out int prosperity)
        {
            residents = NextResidentsNeed; prosperity = NextProsperityNeed;
            return !IsMax;
        }
        /// <summary>스토리 048. 등급이 올랐을 때(거점 id, 새 등급 번호). TierChanged는 hub-1만 낸다.</summary>
        event Action<string, int> HubTierChanged { add { } remove { } }
    }
}
